import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "../App.css";

function Hero() {
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();

  // Animation variants
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.8, ease: "easeOut" },
    },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.2 },
    },
  };

  const floatingAnimation = {
    y: [0, -20, 0],
    transition: {
      duration: 3,
      repeat: Infinity,
      ease: "easeInOut",
    },
  };

  // Button actions
  const handleGetStarted = () => {
    if (isAuthenticated) {
      navigate("/projects");
    } else {
      navigate("/login");
    }
  };

  const handleLearnMore = () => {
    navigate("/about");
  };

  return (
    <div>
      {/* Hero Section */}
      <main
        style={{
          minHeight: "100vh",
          backgroundImage: `
            linear-gradient(to top, rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)), 
            url("https://image.hanssem.com/hsimg/upload/homeIdea/2025/08/27/1756269384558_0d28da.jpg?w=1500")
          `,
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat",
          position: "relative",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "80px 20px 60px",
        }}
      >
        {/* Background Pattern */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background:
              "url('data:image/svg+xml,%3Csvg width=\"60\" height=\"60\" viewBox=\"0 0 60 60\" xmlns=\"http://www.w3.org/2000/svg\"%3E%3Cg fill=\"none\" fill-rule=\"evenodd\"%3E%3Cg fill=\"%23ffffff\" fill-opacity=\"0.05\"%3E%3Cpath d=\"M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z\"/%3E%3C/g%3E%3C/g%3E%3C/svg%3E')",
            opacity: 0.3,
          }}
        />

        {/* Floating Shapes */}
        <motion.div
          style={{
            position: "absolute",
            width: "400px",
            height: "400px",
            borderRadius: "50%",
            background:
              "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.05) 100%)",
            top: "-100px",
            left: "-100px",
            filter: "blur(60px)",
          }}
          animate={floatingAnimation}
        />
        <motion.div
          style={{
            position: "absolute",
            width: "300px",
            height: "300px",
            borderRadius: "50%",
            background:
              "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.05) 100%)",
            bottom: "-50px",
            right: "-50px",
            filter: "blur(60px)",
          }}
          animate={{
            y: [0, 30, 0],
            transition: {
              duration: 4,
              repeat: Infinity,
              ease: "easeInOut",
            },
          }}
        />

        {/* Main Content */}
        <motion.div
          style={{
            maxWidth: "1200px",
            width: "100%",
            position: "relative",
            zIndex: 1,
          }}
          initial="hidden"
          animate="visible"
          variants={staggerContainer}
        >
          <div style={{ textAlign: "left", marginBottom: "80px" }}>
            <motion.div
              style={{
                display: "inline-block",
                padding: "6px 16px",
                background: "rgba(255, 68, 0, 0.08)",
                border: "1px solid rgba(255, 107, 53, 0.4)",
                borderRadius: "30px",
                marginBottom: "25px",
              }}
              variants={fadeUp}
            >
              <span
                style={{
                  fontSize: "11px",
                  fontWeight: "600",
                  color: "#ff6b35",
                  letterSpacing: "0.5px",
                  textTransform: "uppercase",
                }}
              >
                Professional AI Design Platform
              </span>
            </motion.div>

            <motion.h1
              style={{
                fontSize: "clamp(2rem, 5vw, 4rem)",
                fontWeight: 900,
                color: "#fff",
                marginBottom: "25px",
                lineHeight: "1.2",
                textShadow: "2px 2px 4px rgba(0,0,0,0.2)",
              }}
              variants={fadeUp}
            >
              AI-driven Interior
              <br />
              <span
                style={{
                  color: "linear-gradient(155deg, #ff4d00 0%, #ff8c00 100%)",
                  fontWeight: 900,
                }}
              >
                Proposals in Minutes
              </span>
            </motion.h1>

            <motion.p
              style={{
                fontSize: "clamp(0.95rem, 1.5vw, 1.15rem)",
                color: "rgba(255, 255, 255, 0.95)",
                marginBottom: "50px",
                maxWidth: "500px",
                lineHeight: "1.6",
                textAlign: "left",
              }}
              variants={fadeUp}
            >
              ASSEMBLE은 사용자의 요청사항에 맞게
              <br />
              AI 기반 인테리어를 추천합니다
            </motion.p>

            <motion.div
              style={{
                display: "flex",
                gap: "15px",
                justifyContent: "left",
                flexWrap: "wrap",
              }}
              variants={fadeUp}
            >
              <motion.button
                onClick={handleLearnMore}
                style={{
                  padding: "16px 40px",
                  fontSize: "1.05rem",
                  fontWeight: 700,
                  border: "2px solid rgba(255, 255, 255, 0.8)",
                  borderRadius: "12px",
                  background: "rgba(255, 255, 255, 0.05)",
                  backdropFilter: "blur(10px)",
                  color: "#fff",
                  cursor: "pointer",
                }}
                whileHover={{
                  scale: 1.05,
                  background: "rgba(255, 255, 255, 0.1)",
                }}
                whileTap={{ scale: 0.95 }}
              >
                Learn More
              </motion.button>

              <motion.button
                onClick={handleGetStarted}
                style={{
                  padding: "16px 40px",
                  fontSize: "1.05rem",
                  fontWeight: 700,
                  border: "none",
                  borderRadius: "12px",
                  background:
                    "linear-gradient(155deg, #ff3300ff 0%, #ff8c00 100%)",
                  color: "#fff",
                  cursor: "pointer",
                  boxShadow: "0 10px 30px rgba(255, 107, 53, 0.4)",
                }}
                whileHover={{
                  scale: 1.05,
                  boxShadow: "0 15px 40px rgba(255, 107, 53, 0.5)",
                }}
                whileTap={{ scale: 0.95 }}
              >
                Get Started
              </motion.button>
            </motion.div>
          </div>
        </motion.div>
      </main>

      {/* === Features Section === */}
      <motion.div
        style={{
          background: "linear-gradient(180deg, #0a0a0a 0%, #141414 100%)",
          padding: "100px 60px",
          borderTop: "1px solid rgba(255, 255, 255, 0.08)",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div style={{ maxWidth: "1600px", margin: "0 auto" }}>
          <motion.div
            variants={fadeUp}
            style={{ textAlign: "center", marginBottom: "90px" }}
          >
            <h2
              style={{
                fontSize: "clamp(2.5rem, 4vw, 3.0rem)",
                fontWeight: 800,
                color: "#fff",
                marginBottom: "20px",
                letterSpacing: "-1.5px",
              }}
            >
              디자이너를 위한 혁신적인 기능
            </h2>
            <p
              style={{
                fontSize: "1.5rem",
                color: "rgba(255, 255, 255, 0.6)",
              }}
            >
              전문가를 위한 프로페셔널 인테리어 솔루션
            </p>
          </motion.div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
              gap: "30px",
            }}
          >
            {[
              {
                icon: "fas fa-magic",
                title: "AI 자동 생성",
                description:
                  "최첨단 AI 기술로 당신만의 맞춤형 인테리어를 즉시 생성합니다",
              },
              {
                icon: "fas fa-clock",
                title: "빠른 디자인",
                description:
                  "몇 분 안에 다양한 스타일의 인테리어 시안을 확인하세요",
              },
              {
                icon: "fas fa-palette",
                title: "무한한 아이디어",
                description:
                  "다양한 컨셉과 스타일로 당신의 공간을 완벽하게 연출합니다",
              },
              {
                icon: "fas fa-chart-line",
                title: "프로젝트 관리",
                description:
                  "진행 중인 모든 프로젝트를 한눈에 관리하고 추적하세요",
              },
            ].map((feature, index) => (
              <motion.div
                key={index}
                style={{
                  background: "rgba(255, 255, 255, 0.03)",
                  backdropFilter: "blur(20px)",
                  padding: "50px 35px",
                  borderRadius: "20px",
                  border: "1px solid rgba(255, 255, 255, 0.08)",
                  textAlign: "center",
                  cursor: "pointer",
                  overflow: "hidden",
                }}
                variants={fadeUp}
                whileHover={{
                  y: -12,
                  background: "rgba(255, 255, 255, 0.06)",
                  borderColor: "rgba(255, 107, 53, 0.3)",
                }}
              >
                <motion.div
                  style={{
                    width: "90px",
                    height: "90px",
                    margin: "0 auto 30px",
                    borderRadius: "20px",
                    background:
                      "linear-gradient(155deg, #ffffff 10%, #ff4d00 100%)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: "0 15px 40px rgba(255, 107, 53, 0.3)",
                  }}
                  whileHover={{ rotate: 360, scale: 1.1 }}
                  transition={{ duration: 0.6 }}
                >
                  <i
                    className={feature.icon}
                    style={{ fontSize: "2.5em", color: "#fff" }}
                  ></i>
                </motion.div>
                <h3
                  style={{
                    fontSize: "1.5rem",
                    fontWeight: 700,
                    color: "#fff",
                    marginBottom: "16px",
                  }}
                >
                  {feature.title}
                </h3>
                <p
                  style={{
                    fontSize: "1.05rem",
                    color: "rgba(255, 255, 255, 0.65)",
                    lineHeight: "1.7",
                  }}
                >
                  {feature.description}
                </p>
              </motion.div>
            ))}
          </div>
        </div>
      </motion.div>

      {/* === Stats Section === */}
      <motion.div
        style={{
          padding: "120px 80px",
          maxWidth: "1600px",
          margin: "0 auto",
          background: "#0a0a0a",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={staggerContainer}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "space-around",
            flexWrap: "wrap",
            gap: "60px",
            background: "rgba(255, 255, 255, 0.03)",
            backdropFilter: "blur(20px)",
            padding: "90px 60px",
            borderRadius: "25px",
            border: "1px solid rgba(255, 255, 255, 0.08)",
          }}
        >
          {[
            { value: "10,000+", label: "완성된 프로젝트" },
            { value: "5,000+", label: "만족한 사용자" },
            { value: "50+", label: "디자인 스타일" },
            { value: "99%", label: "고객 만족도" },
          ].map((stat, index) => (
            <motion.div
              key={index}
              style={{ textAlign: "center" }}
              variants={fadeUp}
              whileHover={{ scale: 1.08 }}
              transition={{ duration: 0.3 }}
            >
              <h2
                style={{
                  fontSize: "clamp(3rem, 5vw, 4.5rem)",
                  fontWeight: 900,
                  background:
                    "linear-gradient(to bottom, #fff 10%, #ff4d00 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  marginBottom: "15px",
                }}
              >
                {stat.value}
              </h2>
              <p
                style={{
                  fontSize: "1.15rem",
                  color: "rgba(255, 255, 255, 0.79)",
                  margin: 0,
                  fontWeight: 600,
                }}
              >
                {stat.label}
              </p>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </div>
  );
}

export default Hero;
